CREATE TABLE IF NOT EXISTS articles (id BIGSERIAL PRIMARY KEY, title VARCHAR(255) NOT NULL, description VARCHAR(255) NOT NULL, body TEXT NOT NULL, user_id BIGINT NOT NULL, CONSTRAINT fk_articles_user_id__id FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT chk_Articles_unsigned_integer_id CHECK (id BETWEEN 0 AND 4294967295));
CREATE TABLE IF NOT EXISTS tags (id BIGSERIAL PRIMARY KEY, "name" VARCHAR(255) NOT NULL, CONSTRAINT chk_Tags_unsigned_integer_id CHECK (id BETWEEN 0 AND 4294967295));
CREATE TABLE IF NOT EXISTS articletags (article_id BIGINT, tag_id BIGINT, CONSTRAINT pk_ArticleTags PRIMARY KEY (article_id, tag_id), CONSTRAINT fk_articletags_article_id__id FOREIGN KEY (article_id) REFERENCES articles(id) ON DELETE RESTRICT ON UPDATE RESTRICT, CONSTRAINT fk_articletags_tag_id__id FOREIGN KEY (tag_id) REFERENCES tags(id) ON DELETE RESTRICT ON UPDATE RESTRICT);